jobs := make(chan int)
results := make(chan int)

var wg sync.WaitGroup
for w := 0; w < 3; w++ {
    wg.Add(1)
    go func() {
        defer wg.Done()
        for j := range jobs {
            results <- j * j
        }
    }()
}
go func() { wg.Wait(); close(results) }()

go func() {
    for i := 1; i <= 5; i++ {
        jobs <- i
    }
    close(jobs) // закрывает отправитель
}()

sum := 0
for r := range results {
    sum += r
}
fmt.Println(sum)

