package main

import "fmt"

func main() {
    ch := make(chan int, 2)
    ch <- 1
    ch <- 2
    close(ch)
    for v := range ch {
        fmt.Print(v, " ")
    }
    v, ok := <-ch
    fmt.Println(v, ok)
}

func collect(sources []Source) []Item {
    out := make(chan Item)
    for _, s := range sources {
        go func(s Source) {
            for _, it := range s.Fetch() {
                out <- it
            }
            close(out)
        }(s)
    }
    var items []Item
    for it := range out {
        items = append(items, it)
    }
    return items
}

func firstResult(ctx context.Context, replicas []string) (string, error) {
    ch := make(chan string)
    for _, r := range replicas {
        go func(r string) {
            ch <- query(r) // query занимает 10–500 мс
        }(r)
    }
    select {
    case res := <-ch:
        return res, nil
    case <-ctx.Done():
        return "", ctx.Err()
    }
}

